  "automations": {
    "LabelAdd": [
      {
        "name": "Research helper on research label",
        "matcher": "^research$",
        "permissionMode": "allow-all",
        "labels": [
          "automation"
        ],
        "actions": [
          {
            "type": "prompt",
            "prompt": "Research helper for session ${CRAFT_SESSION_ID} (\"${CRAFT_SESSION_NAME}\"). Use @context7 and @brave-search to gather current best practices, official docs, relevant APIs, browser APIs, CSS techniques, existing implementation patterns, and the simplest correct modern approach. Stay in research mode only. Return concise findings the orchestrator can use to create or refine the plan."
          }
        ],
        "id": "8a516e"
      }
    ],
    "SessionStatusChange": [
      {
        "name": "Review helper on needs-review",
        "matcher": "^needs-review$",
        "permissionMode": "allow-all",
        "labels": [
          "automation",
          "review"
        ],
        "actions": [
          {
            "type": "prompt",
            "prompt": "Run @dex-review for implementation session ${CRAFT_SESSION_ID} (\"${CRAFT_SESSION_NAME}\"). Read the linked DEX task from any `task::<id>` label if present. Stay strictly within scope. Verify evidence before approving. Use @chrome-devtools when browser-visible behavior, CSS, DOM, or interaction testing is relevant. Update the original session to `done` or `todo` based on the verdict."
          }
        ],
        "id": "ef6dcb"
      }
    ]
  }
